const KEY='tabacLuxeEnquiry';let cart=JSON.parse(localStorage.getItem(KEY)||'[]');function save(){localStorage.setItem(KEY,JSON.stringify(cart));renderCart();}function addItem(btn){const p={slug:btn.dataset.slug,name:btn.dataset.name,size:btn.dataset.size,price:btn.dataset.price,qty:1};const e=cart.find(x=>x.slug===p.slug);e?e.qty++:cart.push(p);save();toast(p.name+' added to enquiry');openCart();}function renderCart(){document.querySelectorAll('[data-count]').forEach(x=>x.textContent=cart.reduce((s,x)=>s+x.qty,0));const b=document.querySelector('#cartBody');if(!b)return;b.innerHTML=cart.length?cart.map((x,i)=>`<div class="draweritem"><div><b>${esc(x.name)}</b><div class="meta">${esc(x.size)} · ${esc(x.price)}</div><label>Qty <input style="width:70px" type="number" min="1" value="${x.qty}" onchange="qty(${i},this.value)"></label></div><button class="btn" onclick="removeItem(${i})">×</button></div>`).join(''):'<p>Your enquiry list is empty.</p>';}function qty(i,v){cart[i].qty=Math.max(1,parseInt(v)||1);save()}function removeItem(i){cart.splice(i,1);save()}function openCart(){document.querySelector('#drawer')?.classList.add('open')}function closeCart(){document.querySelector('#drawer')?.classList.remove('open')}function enquiryText(){return 'TABAC LUXE TRADE ENQUIRY\n\n'+cart.map(x=>`${x.qty} × ${x.name} — ${x.size} — ${x.price}`).join('\n')+'\n\nPlease confirm trade availability and next steps.'}function sendWA(){if(!cart.length)return toast('Add products first');window.open('https://wa.me/?text='+encodeURIComponent(enquiryText()),'_blank','noopener')}function sendMail(){if(!cart.length)return toast('Add products first');location.href='mailto:?subject='+encodeURIComponent('Tabac Luxe Trade Enquiry')+'&body='+encodeURIComponent(enquiryText())}function toast(t){const e=document.querySelector('.toast');if(!e)return;e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1600)}function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}document.addEventListener('DOMContentLoaded',()=>{renderCart();document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addItem(b));document.querySelectorAll('[data-open-cart]').forEach(b=>b.onclick=openCart);document.querySelectorAll('[data-close-cart]').forEach(b=>b.onclick=closeCart);const q=document.querySelector('#q');const c=document.querySelector('#catFilter');function filter(){const v=(q?.value||'').toLowerCase(),cv=c?.value||'';document.querySelectorAll('.product').forEach(p=>{p.style.display=((!v||p.innerText.toLowerCase().includes(v))&&(!cv||p.dataset.category===cv))?'':'none'})}q?.addEventListener('input',filter);c?.addEventListener('change',filter)});